import { existsSync } from 'node:fs';

import { expect, test } from '../../fixtures/index.ts';
import { shellReady } from '../shell/helpers.ts';

import { IMPORT_PATH, seedBatch, type SeedKind } from './import-helpers.ts';

// `@visual` baselines for the bootstrap import (#553): drop zone, processing, the grid with a
// W.P. + W.M.P. group, an appeal chain, a conflict row, an SR-stage row, the result summary, the
// empty state and the error state. Each runs in the 360/768/1280 light and dark projects.
// Baselines are only ever generated by the e2e workflow's `update_snapshots` dispatch in the
// pinned Playwright image (see e2e/README.md); until they exist each test skips.
type Shot = { name: string; seed: SeedKind | null; review?: boolean; confirm?: boolean };

const SHOTS: Shot[] = [
  { name: 'drop-zone', seed: null },
  { name: 'processing', seed: 'processing' },
  { name: 'grid-wp-wmp', seed: 'grid', review: true },
  { name: 'appeal-chain', seed: 'appealChain', review: true },
  { name: 'conflict-row', seed: 'conflict', review: true },
  { name: 'sr-stage-row', seed: 'srStage', review: true },
  { name: 'result-summary', seed: 'appealChain', review: true, confirm: true },
  { name: 'empty', seed: null },
  { name: 'error', seed: 'failed' },
];

for (const shot of SHOTS) {
  test(
    `bootstrap-import ${shot.name}`,
    { tag: '@visual' },
    async ({ page, asUser, db }, testInfo) => {
      const baseline = testInfo.snapshotPath(`bootstrap-import-${shot.name}.png`, {
        kind: 'screenshot',
      });
      test.skip(
        testInfo.config.updateSnapshots === 'none' && !existsSync(baseline),
        'no baseline yet: dispatch the e2e workflow with update_snapshots',
      );
      const batch = shot.seed === null ? null : await seedBatch(db.name, shot.seed);
      await asUser('owner', {
        path: batch === null ? IMPORT_PATH : `${IMPORT_PATH}?batch=${batch}`,
      });
      await shellReady(page);
      if (shot.review === true) {
        await page.getByRole('button', { name: 'Review the plan' }).click();
        await expect(page.getByRole('heading', { name: 'Confirm what we found' })).toBeVisible();
      }
      if (shot.confirm === true) {
        await page.getByRole('button', { name: /^Confirm 1 matter/ }).click();
        await expect(page.getByText('Import confirmed')).toBeVisible();
      }
      await expect(page).toHaveScreenshot(`bootstrap-import-${shot.name}.png`, { fullPage: true });
    },
  );
}
